BEGIN;
CREATE OR REPLACE FUNCTION public.office_ngo_read(p_workspace_id uuid,p_resource text,p_filter jsonb DEFAULT '{}'::jsonb,p_limit integer DEFAULT 100,p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE role text; caps jsonb; total bigint; rows jsonb; sql text; purpose text; s record; k text; BEGIN role:=office_private.ngo_context(p_workspace_id); IF p_limit NOT BETWEEN 1 AND 100 OR p_offset<0 OR jsonb_typeof(p_filter)<>'object' THEN RAISE EXCEPTION 'Invalid NGO read request' USING ERRCODE='22023'; END IF; IF p_resource='bootstrap' THEN SELECT * INTO s FROM public.office_ngo_settings WHERE workspace_id=p_workspace_id; RETURN jsonb_build_object('actor_id',auth.uid(),'role',role,'capabilities',office_private.ngo_caps(role),'summary',jsonb_build_object(),'settings',jsonb_build_object('base_currency',coalesce(s.base_currency,'TZS'),'jurisdiction',coalesce(s.jurisdiction,'mainland'),'private_data_enabled',coalesce(s.private_data_enabled,false),'storage_review_state',coalesce(s.storage_review_state,'unverified'),'storage_review_reference',coalesce(s.storage_review_reference,''),'version',coalesce(s.version,1),'initialized',coalesce(s.initialized,false))); END IF; IF p_resource='private_keys' THEN IF role NOT IN ('ngo_admin','compliance_officer') THEN RAISE EXCEPTION 'NGO key access denied' USING ERRCODE='42501'; END IF; SELECT jsonb_build_object('beneficiary',coalesce((SELECT jsonb_build_object('configured',configured,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',encode(salt,'base64'),'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64')) FROM public.office_ngo_private_keys WHERE workspace_id=p_workspace_id AND kind='beneficiary'),'{"configured":false}'::jsonb),'safeguarding',coalesce((SELECT jsonb_build_object('configured',configured,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',encode(salt,'base64'),'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64')) FROM public.office_ngo_private_keys WHERE workspace_id=p_workspace_id AND kind='safeguarding'),'{"configured":false}'::jsonb)) INTO rows; RETURN rows; END IF; IF p_resource='members' THEN RETURN (SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'workspace_id',m.workspace_id,'status',m.status,'role',m.role)), '[]'::jsonb),'total_count',count(*),'limit',p_limit,'offset',p_offset,'has_more',false) FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.status='active'); END IF; IF p_resource='roles' THEN RETURN (SELECT jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb),'total_count',count(*),'limit',p_limit,'offset',p_offset,'has_more',false) FROM public.office_ngo_roles r WHERE r.workspace_id=p_workspace_id); END IF; IF p_resource='audit' THEN IF NOT coalesce((office_private.ngo_caps(role)->>'audit')::boolean,false) THEN RAISE EXCEPTION 'Audit capability required' USING ERRCODE='42501'; END IF; END IF; IF p_resource NOT IN ('donors','grants','projects','budget_lines','disbursements','expenses','procurements','partners','subgrants','activities','indicators','measurements','beneficiaries','beneficiary_private','safeguarding','staff_assignments','assets','obligations','governance','evidence','reports','audit') THEN RAISE EXCEPTION 'Unknown NGO resource' USING ERRCODE='22023'; END IF; FOR k IN SELECT jsonb_object_keys(p_filter) LOOP IF k NOT IN ('id','project_id','grant_id','status','purpose') THEN RAISE EXCEPTION 'Unknown NGO filter' USING ERRCODE='22023'; END IF; END LOOP; IF p_resource<>'audit' AND NOT coalesce((office_private.ngo_caps(role)->>office_private.ngo_resource_cap(p_resource))::boolean,false) THEN RAISE EXCEPTION 'NGO capability denied' USING ERRCODE='42501'; END IF; IF p_resource IN ('beneficiary_private','safeguarding') THEN purpose:=p_filter->>'purpose'; IF p_resource='beneficiary_private' AND (NOT (p_filter ? 'id') OR (p_filter->>'id')::uuid IS NULL) THEN RAISE EXCEPTION 'Beneficiary private reads require exact id' USING ERRCODE='22023'; END IF; IF purpose NOT IN ('direct_service','record_correction','safeguarding_response','compliance_review') THEN RAISE EXCEPTION 'Protected read purpose required' USING ERRCODE='22023'; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_settings WHERE workspace_id=p_workspace_id AND private_data_enabled AND storage_review_state='approved') THEN RAISE EXCEPTION 'Private data gate is closed' USING ERRCODE='55000'; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_private_keys WHERE workspace_id=p_workspace_id AND kind=CASE WHEN p_resource='beneficiary_private' THEN 'beneficiary' ELSE 'safeguarding' END AND configured) THEN RAISE EXCEPTION 'Resource-specific private key is not configured' USING ERRCODE='55000'; END IF; INSERT INTO public.office_ngo_audit(workspace_id,actor_id,resource,action,purpose) VALUES(p_workspace_id,auth.uid(),p_resource,'read',purpose); END IF; sql:=format('SELECT count(*) FROM public.office_ngo_%I WHERE workspace_id=$1',p_resource); IF p_filter ? 'id' THEN sql:=sql||format(' AND id=%L',(p_filter->>'id')::uuid); END IF; IF p_filter ? 'project_id' THEN sql:=sql||format(' AND project_id=%L',(p_filter->>'project_id')::uuid); END IF; IF p_filter ? 'grant_id' THEN sql:=sql||format(' AND grant_id=%L',(p_filter->>'grant_id')::uuid); END IF; IF p_filter ? 'status' THEN sql:=sql||format(' AND status=%L',p_filter->>'status'); END IF; EXECUTE sql INTO total USING p_workspace_id; IF p_resource='beneficiary_private' THEN sql:=format('SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) FROM (SELECT id,workspace_id,status,version,beneficiary_id,encode(nonce,''base64'') nonce,encode(ciphertext,''base64'') ciphertext FROM public.office_ngo_beneficiary_private WHERE workspace_id=$1 AND id=%L LIMIT 1) x'); ELSEIF p_resource='safeguarding' AND NOT (p_filter ? 'id') THEN sql:=format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''workspace_id'',workspace_id,''status'',status,''version'',version,''project_id'',project_id,''code'',code,''priority'',priority,''retention_until'',retention_until)),''[]''::jsonb) FROM (SELECT id,workspace_id,status,version,project_id,code,priority,retention_until FROM public.office_ngo_safeguarding WHERE workspace_id=$1 ORDER BY updated_at DESC,id LIMIT $2 OFFSET $3) x'); ELSE sql:=format('SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) FROM (SELECT * FROM public.office_ngo_%I WHERE workspace_id=$1 ORDER BY updated_at DESC,id LIMIT $2 OFFSET $3) x',p_resource); END IF; EXECUTE sql INTO rows USING p_workspace_id,p_limit,p_offset; RETURN jsonb_build_object('rows',rows,'total_count',total,'limit',p_limit,'offset',p_offset,'has_more',p_offset+jsonb_array_length(rows)<total); END$$;
REVOKE ALL ON FUNCTION public.office_ngo_read(uuid,text,jsonb,integer,integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.office_ngo_read(uuid,text,jsonb,integer,integer) TO authenticated;
COMMIT;
